"""Final scoped production checks and illustrated Cyprus research handover."""
import concurrent.futures,csv,html,importlib.util,json,collections
from pathlib import Path
import requests
s=importlib.util.spec_from_file_location('m','ops/cyprus-deep-20261010.py');m=importlib.util.module_from_spec(s);s.loader.exec_module(m)
E=html.escape;BASE='https://artlines.org';OP=m.RUN.name
plans=[m.h.load(m.BACKUP/(w+'-plan.json.gz'))for w in ['wave1','wave2']]
records={r['artwork_id']:r for p in plans for r in p['records']}
images=[im for w in ['wave1','wave2']for im in m.h.load(m.RUN/(w+'-images-reviewed.json'))]
new={r['artwork_id']for p in plans for r in p['records']if not r['before']}
baseline=m.h.load(m.RUN/'baseline.json.gz');before={i['id']:i for i in baseline['museums']}
def snapshot():
    with m.d.connect()as db,db.transaction():
        db.execute('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ ONLY')
        ids=list(before)
        counts=db.execute("SELECT i.id::text,i.slug,i.name,count(a.id)artworks,count(a.primary_media_id)images FROM institutions i LEFT JOIN artworks a ON a.current_institution_id=i.id AND a.status<>'archived'WHERE i.id=ANY(%s::uuid[])GROUP BY i.id ORDER BY i.name",(ids,)).fetchall()
        # Only this Cyprus institution cohort; prefer new delivered images for the illustrated report.
        reps=db.execute("SELECT DISTINCT ON(a.current_institution_id)a.current_institution_id::text institution_id,a.id::text,a.title,a.date_display,a.primary_media_id::text,m.storage_path,m.source_page_url,m.attribution_text,am.view_label FROM artworks a JOIN media_assets m ON m.id=a.primary_media_id LEFT JOIN artwork_media am ON am.artwork_id=a.id AND am.media_id=m.id WHERE a.current_institution_id=ANY(%s::uuid[])AND a.status<>'archived'ORDER BY a.current_institution_id,(a.id=ANY(%s::uuid[]))DESC,a.id",(ids,[x['artwork_id']for x in images])).fetchall()
        rows=db.execute("SELECT a.id::text,a.status,a.published_at,a.current_institution_id::text,a.primary_media_id::text,artline_has_selection_evidence(a.id)selected FROM artworks a WHERE a.id=ANY(%s::uuid[])",(list(records),)).fetchall()
        for a in rows:
            assert a['selected']and a['current_institution_id']==records[a['id']]['museum']['id']
            if a['id']in new:assert a['status']=='review'and a['published_at']is None
        assert not db.execute("SELECT 1 FROM artwork_location_assertions WHERE artwork_id=ANY(%s::uuid[])AND claim_type='display'",(list(new),)).fetchone()
    m.h.save(m.RUN/'final-snapshot.json',dict(at=m.h.now(),target='production',museums=counts,representatives=reps,selected_artworks=rows))
    return counts,reps
def public_checks():
    def check(r):
        aid=r['artwork_id'];u=BASE+'/api/backend/v1/atlas/artworks/'+aid
        response=requests.get(u,timeout=(15,45))
        if response.status_code==404 and r['fact']['precision']in {'before','after','unknown'}:
            return dict(id=aid,status=404,reason='Atlas intentionally requires a bounded creation interval; the source-backed catalogue record and image remain present. No date was invented to enter the timeline.',public_without_login=False)
        response.raise_for_status();v=response.json();assert v['id']==aid and v['title']==r['fact']['title']
        im=next((x for x in images if x['artwork_id']==aid),None)
        if im:assert v['media_url']==im['path']
        if aid in new:assert v['status']=='review'
        return dict(id=aid,status=response.status_code,image=v.get('media_url'),public_without_login=True)
    with concurrent.futures.ThreadPoolExecutor(max_workers=4)as pool:checks=list(pool.map(check,records.values()))
    m.h.save(m.RUN/'public-artwork-verification.json',dict(at=m.h.now(),checked=len(checks),successful=sum(x['status']==200 for x in checks),expected_atlas_scope_exclusions=[x for x in checks if x['status']==404],unexpected_errors=0,checks=checks))
    print('PUBLIC ARTWORKS',len(checks),flush=True)
def report(counts,reps):
    sources=m.h.load(m.RUN/'directory-audit.json')['sources'];src={s['url']:s for s in sources};rep={r['institution_id']:r for r in reps}
    stats=dict(institution_records=169,directory_urls=len(sources),successful_directory_responses=sum(s.get('status')==200 for s in sources),new_artworks=len(new),image_attachments=len(images),artworks=sum(x['artworks']for x in counts),illustrated_artworks=sum(x['images']for x in counts),nonempty_museums=sum(x['artworks']>0 for x in counts),illustrated_museums=sum(x['images']>0 for x in counts),tours=7,tour_hotspots=174,university_object_records=219,publication_changes=0,local_database_writes=0)
    gaps={
      'archbishop-kyprianos-museum-strovolos':'The municipality identifies seven icons/textiles, but its six photographs show buildings or wide interiors without a secure exact-object match. Later 1957/1959 paintings also exceed the approved image cutoff.',
      'dervish-pasha-museum-nicosia':'The official museum brochure supports the ceiling dated 1869. Its pictures instead show undated furniture and vessels. A Commons gallery was located, but preview delivery returned 403; no ceiling image was attached.',
      'lapidary-museum-nicosia':'Sources identify Adam de Gaures’s tombstone. The tourism archive image is a broad courtyard view; no secure pictured tombstone identity. The Dampierre sarcophagus and lion remain object-research leads.',
      'cyprus-byzantine-museum-of-the-holy-bishopric-of-tamasos-and-oreinis-2':'Four distinct inventory-numbered icons/crosses added. BYZART original downloads returned 401; a separately published church catalogue returned 403. Metadata remains available, images remain unfilled.'}
    coverage=[]
    for x in counts:
        b=before[x['id']];rs=[r for r in records.values()if r['museum']['id']==x['id']];ims=[im for im in images if im['museum_slug']==x['slug']]
        coverage.append(dict(name=x['name'],slug=x['slug'],city=b['city'],website=b['website_url']or'',directory_http=src.get(b['website_url'],{}).get('status','no website'),before_artworks=b['artworks'],artworks=x['artworks'],new_artworks=sum(r['artwork_id']in new for r in rs),before_images=b['images'],images=x['images'],images_added=len(ims),research_depth='Object-level selection and source review'if rs else'Existing illustrated collection checked'if x['images']else'Object-image follow-up'if x['slug']in gaps else'Directory source checked; object research incomplete',remaining_gap=gaps.get(x['slug'],'Additional eligible object records and exact image matching remain open.'if x['artworks']else'No eligible object selected in this pass. Directory presence is not artwork coverage.')))
    m.h.save(m.RUN/'final-stats.json',stats);m.h.save(m.RUN/'museum-coverage.json',coverage)
    with(m.RUN/'museum-coverage.csv').open('w',newline='')as f:
        wr=csv.DictWriter(f,fieldnames=list(coverage[0]));wr.writeheader();wr.writerows(coverage)
    inventory=[]
    for aid,r in records.items():
        f=r['fact'];im=next((x for x in images if x['artwork_id']==aid),None)
        inventory.append(dict(artwork_id=aid,museum=r['museum']['name'],title=f['title'],date=f['date_display'],creator=f['creator']or'Unknown / not supplied',new=aid in new,image_added=bool(im),source=f['source_url'],source_record=f['source_record_id'],image_url=BASE+im['path']if im else'',image_view=im['view_label']if im else'',rights=im['rights_label']if im else'',accession=f['accession']or''))
    with(m.RUN/'delivered-artworks.csv').open('w',newline='')as f:
        wr=csv.DictWriter(f,fieldnames=list(inventory[0]));wr.writeheader();wr.writerows(inventory)
    cards=[]
    for x in counts:
        if not x['images']:continue
        r=rep[x['id']];c=next(y for y in coverage if y['slug']==x['slug']);image=BASE+r['storage_path'];source=r['source_page_url']or c['website'];museum=BASE+'/museums/'+x['slug']
        cards.append(f'<article id="{E(x["slug"])}"><figure><a href="{E(image)}"><img src="{E(image)}" alt="{E(r["title"])}"></a><figcaption>{E(r["view_label"]or"Source photograph; complete supplied frame")}</figcaption></figure><div class="cardbody"><p class="place">{E(c["city"])}</p><h3><a href="{E(museum)}">{E(x["name"])}</a></h3><p><strong>{E(r["title"])}</strong><br>{E(r["date_display"]or"Creation date unknown")}</p><p class="count">{x["artworks"]} catalogue works · {x["images"]} illustrated<br>Added here: {c["new_artworks"]} works / {c["images_added"]} pictures</p><p class="credit">{E(r["attribution_text"]or"See original source for credits and rights.")}</p><a class="source" href="{E(source)}">Artwork image source ↗</a></div></article>')
    gapcards=''.join(f'<li><strong>{E(x["name"])}</strong><p>{E(gaps.get(x["slug"],"Exact artwork image remains unresolved."))}</p></li>'for x in counts if x['artworks']and not x['images'])
    rows=''.join(f'<tr><td>{E(c["name"])}</td><td>{E(c["city"])}</td><td>{c["artworks"]}</td><td>{c["images"]}</td><td>{E(c["research_depth"])}</td><td>'+ (f'<a href="{E(c["website"])}">Source</a>'if c['website']else'Additional sources in inventory')+'</td></tr>'for c in coverage)
    doc='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cyprus: artworks in museum collections — Artline research</title><style>
*{box-sizing:border-box}body{margin:0;background:#f6f3ec;color:#243332;font:17px/1.55 Georgia,serif}main{max-width:1160px;margin:auto;padding:44px 28px 90px}a{color:#175f61;text-underline-offset:3px}h1{font-size:clamp(34px,5vw,64px);line-height:1.08;max-width:900px;margin:12px 0 24px}h2{font-size:29px;margin-top:52px}h3{font-size:23px;line-height:1.2;margin:4px 0 14px}.eyebrow,.place,.count,.credit,nav,table,.stats{font-family:Arial,sans-serif}.eyebrow{letter-spacing:2px;font-size:12px;text-transform:uppercase;color:#596d6b}.intro{max-width:900px;font-size:20px}.stats{display:flex;flex-wrap:wrap;gap:24px;padding:24px 0;border-top:1px solid #b9c8c0;border-bottom:1px solid #b9c8c0}.stats strong{display:block;font-size:37px;color:#175f61}.stats span{font-size:14px}nav{display:flex;flex-wrap:wrap;gap:24px;margin:25px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}article{background:white;border:1px solid #d9dfd8;overflow:hidden}figure{margin:0;padding:20px 20px 12px;background:#e9e8e1}figure img{width:100%;height:300px;object-fit:contain;display:block}figcaption{font:12px/1.45 Arial,sans-serif;color:#51605d;margin-top:10px}.cardbody{padding:22px 25px 26px}.place{font-size:12px;letter-spacing:1px;text-transform:uppercase;margin:0;color:#687570}.count{font-size:13px}.credit{font-size:11px;color:#5b6663}.source{font:13px Arial,sans-serif}.notice{padding:20px 24px;background:#e8eee7;border-left:4px solid #7c9483}.gaplist{padding-left:22px}.gaplist li{margin:20px 0}.gaplist p{margin:5px 0}.tablewrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:12px}td,th{text-align:left;padding:12px 10px;border-bottom:1px solid #ccd4cc;vertical-align:top}th{background:#e8eee7}footer{margin-top:50px;font:13px Arial,sans-serif;color:#5b6663}@media(max-width:700px){main{padding:24px 16px 60px}.grid{grid-template-columns:1fr}figure img{height:260px}.stats{gap:20px}.intro{font-size:18px}}@media print{article{break-inside:avoid}nav{display:none}body{background:white}main{padding:0}.grid{gap:14px}}
</style><main><div class="eyebrow">Artline · Cyprus collection research · 10 October 2026</div><h1>Cyprus, through its museum artworks</h1>'''
    doc+=f'<p class="intro"><strong>{stats["new_artworks"]} new artwork records and {stats["image_attachments"]} authentic artwork pictures delivered to production.</strong> This report gives one illustrated example for each of the {stats["illustrated_museums"]} museums that now has an image. {stats["nonempty_museums"]-stats["illustrated_museums"]} further museums have catalogued works but still need a verified picture.</p><div class="stats"><span><strong>{stats["institution_records"]}</strong>institution records checked</span><span><strong>{stats["new_artworks"]}</strong>new works</span><span><strong>{stats["image_attachments"]}</strong>pictures attached</span><span><strong>{stats["illustrated_museums"]} / {stats["nonempty_museums"]}</strong>nonempty museums illustrated</span></div><nav><a href="#pictures">Museum artwork pictures</a><a href="#gaps">Remaining image gaps</a><a href="#method">Research and verification</a><a href="#coverage">All 169 records</a><a href="delivered-artworks.csv">Artwork inventory CSV</a></nav><p class="notice">New records remain in review and are available through the unified catalogue. Museum links require sign-in under Artline’s existing access policy. Collection holdings are documented separately from current display; this report makes no fresh on-view claims.</p><h2 id="pictures">One artwork image per illustrated museum</h2><div class="grid">'+''.join(cards)+'</div><h2 id="gaps">Remaining image gaps</h2><p>No building photographs or invented artworks were used to fill these gaps.</p><ul class="gaplist">'+gapcards+'</ul>'
    doc+='''<h2 id="method">Research and verification</h2><p>The pass checked 113 distinct directory source URLs for 169 existing Cyprus institution records: 112 responded successfully, and one returned 403. A directory check is not a claim that every collection has been fully researched. Object work included 174 captioned hotspots across seven officially linked Larnaka museum tours, 219 BYZART museum records hosted by the University of Bologna, the Department of Antiquities’ <em>Ancient Cyprus: Cultures in Dialogue</em>, the Cyprus Tourism Organisation’s <em>Island of Saints</em>, individual museum pages, and a Metropolitan Museum exhibition catalogue.</p>
<p>Each selected addition was checked against existing museum records, source identifiers, dates and object versions. Seven detached Kykkos murals and four Tamasos objects preserve inventory numbers and unknown creators. The Tamasos Saint George attribution retains its question mark. Repeated tour hotspots, photograph details, reverse sides and a possible Pierides accession duplicate were not created as separate artworks. Two ambiguous Kykkos cross/icon matches remain held.</p>
<p>Visual review rejected six misleading source pictures, including a coat of arms, procession, modern priest and a different biblical scene. Some archaeological sources supply a complete multi-object plate; the attached view label identifies the object’s position. The Lampadistis illustration is explicitly a detail. The Pedoulas reproduction retains the complete supplied catalogue page and identifies catalogue object 93. These limitations remain visible in the metadata.</p>
<p>All delivered JPEGs preserve the source frame and are at most 100,000 bytes. Restricted source rights remain restricted; owner workflow approval is recorded separately and does not assert a licence from a rights holder. Originals, captures, source hashes, plans and recovery preimages are retained. Protected image endpoints were left unfilled. No generated artwork images were used.</p>
<p>Two initial catalogue transactions rolled back entirely on HTTPS evidence-field constraints. The successful transaction retains the original HTTP source URLs in evidence and identifies the HTTPS storage copies separately. Image delivery was verified through Artline’s public asset route; the storage bucket itself is private. Existing catalogue metadata, creator links and publication states were preserved. The local database received no writes. No deployment, commit or infrastructure change was performed.</p>
<p>Validation covers exact database rows, source-backed selection evidence, new review states, unchanged creator links, storage byte hashes and all 86 public image responses. Of 117 affected artwork detail checks, 116 returned successfully through the public atlas. The silk bridal outfit has only a documented upper date bound (worn by 1898), so the atlas correctly excludes it from its bounded-date timeline; its catalogue record and public image were verified separately. Museum browsing requires login. These are bounded content checks, not a ten-million-row performance test.</p>
<p>Primary sources: <a href="https://virtuallarnakaregion.com/PieridesMuseum/">Pierides official virtual tour</a> · <a href="https://historica.unibo.it/entities/fonds/1394ec01-fd47-4ef2-859e-f55c429ff5b4">Kykkos BYZART collection</a> · <a href="https://historica.unibo.it/entities/fonds/0affef79-2a92-464d-a195-091092c4367c">Tamasos BYZART collection</a> · <a href="https://www.visitcyprus.com/wp-content/uploads/files/cultural_routes/Cyprus_island_of_saints_EN.pdf">Island of Saints</a> · <a href="https://libmma.contentdm.oclc.org/digital/collection/p15324coll10/id/58371">Byzantium: Faith and Power</a>. Exact object and image links appear in the accompanying inventory.</p>
<h2 id="coverage">Coverage ledger: all 169 institution records</h2><p>Empty institutions are preserved for research and remain excluded from museum browsing. No new artwork was invented to make an institution visible. For complete per-museum gap notes, download <a href="museum-coverage.csv">the coverage CSV</a>.</p><div class="tablewrap"><table><thead><tr><th>Institution</th><th>Locality</th><th>Works</th><th>Images</th><th>Depth reached</th><th>Directory source</th></tr></thead><tbody>'''+rows+'</tbody></table></div><footer>Prepared from evidence captured and production checks performed on 10 October 2026. Source publication dates vary; historical descriptions do not confirm present-day display.</footer></main></html>'
    (m.RUN/'report.html').write_text(doc)
    print(json.dumps(stats),flush=True)
